const R = String.raw;

export default [
  {
    id: 'quantization', title: 'Quantisation in depth', tracks: ['auto', 'cv', 'mlops', 'mle', 'genai'],
    tasks: [
      {
        id: 'q-params', title: 'Scale and zero point',
        prompt: `Write \`qparams(xmin, xmax, signed=True)\` that returns \`(scale, zero_point)\` for 8-bit affine quantisation of the float range \`[xmin, xmax]\`.

1. The range must contain 0: use \`xmin = min(xmin, 0)\` and \`xmax = max(xmax, 0)\`.
2. Integer range: \`qmin, qmax = -128, 127\` if signed, else \`0, 255\`.
3. \`scale = (xmax - xmin) / (qmax - qmin)\`. If the range is empty, return \`(1.0, 0)\`.
4. \`zero_point = round(qmin - xmin / scale)\`, clipped to \`[qmin, qmax]\`, as an int.`,
        starter: R`def qparams(xmin, xmax, signed=True):
    pass

print(qparams(0.0, 6.0))  # (0.0235..., -128)
`,
        solution: R`def qparams(xmin, xmax, signed=True):
    xmin, xmax = min(xmin, 0.0), max(xmax, 0.0)
    qmin, qmax = (-128, 127) if signed else (0, 255)
    if xmax == xmin:
        return 1.0, 0
    scale = (xmax - xmin) / (qmax - qmin)
    zero_point = int(round(qmin - xmin / scale))
    return scale, max(qmin, min(qmax, zero_point))
`,
        tests: [
          { name: 'ReLU6 output, signed', code: R`s, z = qparams(0.0, 6.0)
assert close(s, 6 / 255) and z == -128, 'Range [0, 6] signed: scale 6/255, zero point -128'` },
          { name: 'Symmetric-ish range', code: R`s, z = qparams(-1.28, 1.27)
assert close(s, 0.01) and z == 0, 'Range [-1.28, 1.27]: scale 0.01, zero point 0'` },
          { name: 'Unsigned', code: R`s, z = qparams(-1.0, 3.0, signed=False)
assert close(s, 4 / 255) and z == 64, 'Unsigned [-1, 3]: scale 4/255, zero point 64'` },
          { name: 'Range is widened to include zero', code: R`s, z = qparams(1.0, 5.0)
assert close(s, 5 / 255) and z == -128, 'Zero must be exactly representable, so [1, 5] becomes [0, 5]'
assert qparams(0.0, 0.0) == (1.0, 0), 'Empty range returns (1.0, 0)'` }
        ]
      },
      {
        id: 'q-q15', title: 'Q15 fixed-point multiply',
        prompt: `Microcontrollers without a floating-point unit store fractions as integers. In **Q15**, an \`int16\` value \`v\` represents \`v / 32768\`.

Write \`q15_mul(a, b)\` that multiplies two Q15 numbers and returns a Q15 number:

1. \`product = a * b\` (fits in 32 bits)
2. Round: add \`1 << 14\`, then shift right by 15.
3. Saturate the result to \`[-32768, 32767]\`.`,
        starter: R`def q15_mul(a, b):
    pass

print(q15_mul(16384, 16384))  # 0.5 * 0.5 = 0.25 -> 8192
`,
        solution: R`def q15_mul(a, b):
    result = (a * b + (1 << 14)) >> 15
    return max(-32768, min(32767, result))
`,
        tests: [
          { name: 'Half times half', code: R`assert q15_mul(16384, 16384) == 8192, '0.5 * 0.5 = 0.25, which is 8192 in Q15'` },
          { name: 'Negative operand', code: R`assert q15_mul(16384, -16384) == -8192, '0.5 * -0.5 = -0.25'` },
          { name: 'Saturation', code: R`assert q15_mul(-32768, -32768) == 32767, '-1 * -1 = +1 cannot be represented: saturate to 32767'` },
          { name: 'Rounding', code: R`assert q15_mul(32767, 1) == 1 and q15_mul(3, 16384) == 2, 'Add 1 << 14 before shifting so the result is rounded, not truncated'` }
        ]
      }
    ],
    quiz: [
      { q: 'Why must the float value 0.0 map exactly to an integer?', options: ['It makes training faster', 'Zero padding and ReLU outputs must stay exactly zero or errors accumulate', 'Integers cannot be negative', 'It is only a convention'], answer: 1, why: 'That is the reason for the zero point in affine quantisation.', level: 'easy' },
      { q: 'Per-channel quantisation of convolution weights helps because…', options: ['It uses fewer bits', 'Channels have very different weight ranges, so one shared scale wastes resolution', 'It removes the need for calibration', 'It makes activations symmetric'], answer: 1, why: 'Each output channel gets its own scale. It is standard for convolution weights.', level: 'medium' },
      { q: 'Post-training quantisation loses too much accuracy. Next step?', options: ['Use 4 bits', 'Quantisation-aware training, or keep sensitive layers in higher precision', 'Remove batch norm', 'Lower the learning rate'], answer: 1, why: 'QAT simulates rounding during training so the weights adapt. Mixed precision keeps the fragile layers in float or 16-bit.', level: 'medium' },
      { q: 'Which is usually most sensitive to quantisation?', options: ['The middle convolution layers', 'The first and last layers, and layers with wide outlier-heavy ranges', 'Pooling layers', 'Padding'], answer: 1, why: 'Outliers stretch the range, so most values share few integer levels.', level: 'medium' },
      { q: 'Quantisation is mainly used to…', options: ['Add more layers', 'Collect more training data', 'Increase the number of classes', 'Shrink the model and speed up inference'], answer: 3, why: 'Fewer bits per number means less memory and cheaper arithmetic.', level: 'easy' },
      { q: 'How many bytes does one int8 weight occupy?', options: ['1', '2', '4', '8'], answer: 0, why: 'Eight bits make one byte, a quarter of a float32.', level: 'easy' },
      { q: 'In q = round(x / scale) + zero_point, what does scale represent?', options: ['The size of one integer step, in float units', 'The number of bits used', 'The learning rate', 'The number of channels'], answer: 0, why: 'A larger scale means coarser steps and a wider representable range.', level: 'easy' },
      { q: 'A tensor has range [-6, 6]. Symmetric int8 uses integers -127 to 127. About what is the scale?', options: ['0.094', '0.012', '0.047', '0.5'], answer: 2, why: '6 / 127 is about 0.047.', level: 'medium' },
      { q: 'With scale 0.5 and zero point 0, the float 1.3 is quantised and then dequantised. What value comes back, and what is the error?', options: ['1.0, error 0.3', '1.5, error 0.3', '1.5, error 0.2', '2.0, error 0.7'], answer: 2, why: 'round(1.3 / 0.5) = round(2.6) = 3, and 3 × 0.5 = 1.5, which is 0.2 above 1.3.', level: 'hard' },
      { q: 'Q15 with rounding: a = 16384 (0.5) and b = -8192 (-0.25). What does (a × b + (1 << 14)) >> 15 give, using an arithmetic shift?', options: ['-4095', '4096', '-8192', '-4096'], answer: 3, why: 'The product is -134217728; adding 16384 and shifting right by 15 gives -4096, which is -0.125.', level: 'hard' },
      { q: 'int8 per-tensor quantisation badly hurts one depthwise convolution layer while the others are fine. Most likely reason and fix?', options: ['Its channels have very different ranges; use per-channel scales', 'Depthwise layers cannot be integers; always use float', 'The calibration set is too large; use fewer samples', 'Batch norm is missing; add dropout'], answer: 0, why: 'One shared scale wastes resolution on channels with small ranges.', level: 'hard' },
      { q: 'The int8 model is accurate in the Python simulation but poor on the device. Where do you look first?', options: ['The learning rate', 'The device’s integer rounding, saturation and shifts compared with the simulation, and preprocessing', 'The number of epochs', 'The dataset licence'], answer: 1, why: 'Small differences in integer arithmetic or preprocessing between simulation and target are the usual cause.', level: 'hard' }
    ],
    interview: [
      { q: 'Explain post-training quantisation and quantisation-aware training.', level: 'medium', points: [['Quantisation maps float weights and activations to low-bit integers', ['integer', 'int8', '8-bit', '8 bit', 'low-bit']], ['PTQ: after training, with a calibration set to find ranges', ['calibrat', 'after training', 'post-training', 'post training']], ['QAT: simulate rounding during training (fake quantisation)', ['fake', 'during training', 'simulat', 'straight-through', 'straight through']], ['Trade-off: PTQ is cheap, QAT recovers accuracy', ['accuracy', 'cheap', 'recover', 'trade']]], model: 'Quantisation replaces 32-bit floats with low-bit integers, usually 8-bit, using a scale and a zero point per tensor or per channel. Post-training quantisation takes a trained model, runs a few hundred representative samples through it to measure activation ranges, and picks the scales; it needs no retraining and often costs under one percent of accuracy. Quantisation-aware training inserts fake-quantisation operations that round in the forward pass and pass gradients straight through in the backward pass, so the weights learn to tolerate the rounding. I start with post-training quantisation and move to QAT only when the accuracy drop is too large, for example with small models or 4-bit targets.' },
      { q: 'A quantised model is much less accurate than the float model. How do you debug it?', level: 'hard', points: [['Compare layer by layer against the float model', ['layer by layer', 'per layer', 'each layer', 'layer-wise']], ['Check the calibration data is representative', ['calibrat', 'representative']], ['Look for outliers and wide ranges; try per-channel or clipping', ['outlier', 'per-channel', 'per channel', 'clip', 'percentile', 'range']], ['Keep sensitive layers in higher precision or use QAT', ['sensitive', 'mixed precision', 'qat', 'quantisation-aware', 'quantization-aware', 'float']]], model: 'I compare the quantised and float models layer by layer on the same inputs and find where the error first becomes large. Common causes are an unrepresentative calibration set, a layer whose range is stretched by outliers, activations after an addition or concatenation with mismatched scales, and preprocessing that differs from training. I try per-channel weight quantisation, a percentile or entropy-based range instead of min and max, and batch-norm folding checks. If one or two layers are responsible, I keep them in float or 16-bit. If the loss is spread across the network, I use quantisation-aware training.' },
      { q: 'How would you run a model on a microcontroller without a floating-point unit?', level: 'hard', points: [['Integer-only inference with fixed-point arithmetic', ['integer', 'fixed-point', 'fixed point', 'q15', 'q7']], ['Scales implemented as integer multiplier plus shift', ['multiplier', 'shift']], ['Saturation and rounding handled explicitly', ['saturat', 'round', 'overflow']], ['Verify against the float reference; measure memory and timing', ['verif', 'reference', 'bit-exact', 'memory', 'timing', 'compare']]], model: 'I convert the model to integer-only inference. Weights and activations are 8-bit or 16-bit integers, and each real-valued scale is replaced by an integer multiplier and a right shift, so no float operation remains. Accumulators are 32-bit, and I handle rounding and saturation explicitly so overflow never wraps around. For signal-processing blocks I use Q-format fixed point such as Q15. I use an optimised kernel library for the target where one exists, for example CMSIS-NN on Arm Cortex-M. Then I verify bit-exactness against a Python reference of the same integer arithmetic, check accuracy against the float model, and measure flash, RAM and worst-case execution time on the device.' },
      { q: 'What is quantisation and why is it used?', level: 'easy', points: [['Representing weights and activations with fewer bits, such as 8-bit integers instead of 32-bit floats', ['fewer bits', '8-bit', 'int8', 'integer', 'lower precision', 'low precision', 'float']], ['Smaller model: about four times less memory for eight-bit', ['smaller', 'memory', 'size', 'four', '4x', 'storage']], ['Faster inference and lower energy on hardware with integer support', ['faster', 'speed', 'latency', 'energy', 'power', 'integer', 'hardware']], ['Cost: some accuracy loss, which must be measured', ['accuracy', 'loss', 'measure', 'degrad', 'trade', 'error']]], model: 'Quantisation stores and computes a model with fewer bits per number, typically eight-bit integers instead of thirty-two-bit floats. The model becomes about four times smaller, which helps when memory is the limit, and memory bandwidth drops too. On hardware with fast integer units, inference is also quicker and uses less energy, which matters on phones, microcontrollers and in automotive devices. The price is rounding error, so accuracy can fall. With a good method and calibration the drop is often tiny, but I always measure it on a real evaluation set and check the sensitive layers.' },
      { q: 'Compare FP32, FP16, bfloat16 and INT8.', level: 'easy', points: [['FP32 is the standard training precision with a wide range and fine precision', ['fp32', '32', 'standard', 'training', 'single']], ['FP16 halves memory with a narrow range, so it can overflow and needs loss scaling', ['fp16', 'half', '16', 'overflow', 'range', 'loss scal', 'narrow']], ['bfloat16 keeps the FP32 range with fewer mantissa bits, so it is more stable for training', ['bfloat', 'bf16', 'range', 'exponent', 'stable', 'mantissa']], ['INT8 uses integers with a scale; it needs calibration but is the fastest and smallest for inference', ['int8', 'integer', 'scale', 'calibrat', 'inference', 'fastest', 'smallest']]], model: 'FP32 is the default for training: a wide range and fine precision, at four bytes per value. FP16 halves that, but its narrow exponent range means values can overflow or underflow, so training uses loss scaling. bfloat16 is also two bytes, but it keeps the same exponent range as FP32 and has fewer mantissa bits, so it is much more stable for training and needs no loss scaling. INT8 stores integers plus a scale factor, so it needs calibration or quantisation-aware training, but it gives the smallest size and often the fastest inference on supporting hardware. I choose by hardware support and accuracy.' },
      { q: 'What are the scale and zero-point in affine quantisation?', level: 'easy', points: [['The scale is the step size: the real value represented by one integer step', ['scale', 'step', 'size', 'multiplier', 'resolution']], ['The zero-point is the integer that represents real zero', ['zero-point', 'zero point', 'represents zero', 'offset', 'integer']], ['Formula: q equals round of x over scale plus zero-point, and x is approximately scale times q minus zero-point', ['round', 'formula', 'q', 'dequant', 'approximately', 'clip', 'clamp']], ['They are derived from the observed min and max, or from calibration', ['min', 'max', 'range', 'calibrat', 'observe', 'derive']]], model: 'In affine quantisation a real value x is mapped to an integer q using two parameters. The scale is the step size, meaning how much real value one integer step represents. The zero-point is the integer that stands for exactly real zero, which matters because zero must be represented exactly, for example for padding and ReLU. The mapping is q equals round of x divided by scale, plus the zero-point, clipped to the integer range, and to go back, x is about scale times q minus zero-point. I compute both from the minimum and maximum of the tensor, found during calibration.' },
      { q: 'Explain per-tensor versus per-channel and symmetric versus asymmetric quantisation.', level: 'medium', points: [['Per-tensor uses one scale for the whole tensor; per-channel gives each output channel its own scale', ['per-tensor', 'per tensor', 'per-channel', 'per channel', 'own scale', 'one scale', 'channel']], ['Per-channel is more accurate for weights whose channels have very different ranges', ['accura', 'range', 'different', 'weights', 'convolution', 'better']], ['Symmetric: the range is centred on zero and the zero-point is zero, which is simpler and faster', ['symmetric', 'centred', 'centered', 'zero-point is zero', 'simple', 'fast']], ['Asymmetric uses a zero-point to fit skewed ranges such as ReLU outputs, with more computation', ['asymmetric', 'skew', 'relu', 'zero-point', 'range', 'offset']]], model: 'Per-tensor quantisation uses one scale for a whole tensor. Per-channel gives each output channel of a convolution or linear layer its own scale. Because channels in a trained network can have very different ranges, per-channel is noticeably more accurate for weights, at a small bookkeeping cost, and it is widely supported. Symmetric quantisation puts the range symmetrically around zero so the zero-point is zero, which makes the integer arithmetic simpler and faster. Asymmetric quantisation adds a zero-point so the integer range fits skewed data, such as activations after a ReLU, using the range better but needing extra terms in the computation.' },
      { q: 'What is the difference between dynamic and static quantisation, and between weight-only and full quantisation?', level: 'medium', points: [['Static quantisation fixes activation scales in advance using a calibration set', ['static', 'calibrat', 'fixed', 'in advance', 'offline', 'activation']], ['Dynamic quantisation computes activation scales at run time from the actual values', ['dynamic', 'run time', 'runtime', 'on the fly', 'actual', 'compute']], ['Weight-only quantisation shrinks the model but computes in higher precision', ['weight-only', 'weight only', 'shrink', 'memory', 'higher precision', 'dequant']], ['Full integer quantisation of weights and activations gives the best speed on integer hardware', ['full', 'integer', 'both', 'activation', 'speed', 'hardware', 'integer-only']]], model: 'In static quantisation I run a small calibration set through the model once to fix the scales for activations, so at inference everything is predetermined and can be pure integer arithmetic, which is the fastest. In dynamic quantisation the weights are quantised ahead of time but activation scales are computed on the fly from each input, which is easier because it needs no calibration data, but slower and less suited to microcontrollers. Weight-only quantisation just compresses the stored weights, saving memory and bandwidth, but the arithmetic still happens in higher precision. I choose according to what is limiting me: size, speed or hardware support.' },
      { q: 'Why is INT8 not always four times faster than FP32, and how do you estimate real gains?', level: 'medium', points: [['Memory bandwidth and size shrink fourfold, but compute speed-up depends on hardware support for integer operations', ['bandwidth', 'memory', 'hardware', 'support', 'integer', 'compute', 'four']], ['Overheads: quantise and dequantise operations, unsupported operators falling back to float', ['overhead', 'dequant', 'fallback', 'fall back', 'unsupported', 'operator', 'convert']], ['Small or memory-bound layers gain less; some layers stay in float', ['memory-bound', 'memory bound', 'small', 'layer', 'float', 'bottleneck']], ['Measure on the target with the real runtime rather than trusting theory', ['measure', 'target', 'benchmark', 'profile', 'runtime', 'real']]], model: 'Storage and memory traffic do shrink four times, but speed depends on the hardware. If the chip has fast integer or vector instructions, compute improves a lot; if not, the gain may be small. There are also overheads: quantise and dequantise steps at the edges, and operators with no integer implementation that fall back to float and force conversions in between. Layers that are memory-bound or tiny gain less than big matrix multiplies. So I never trust the theoretical ratio. I convert the model with the real runtime, profile it on the target device, and compare latency, memory and accuracy against the float baseline.' },
      { q: 'How would you quantise a large language model to 4-bit, and what do you worry about?', level: 'hard', points: [['Weight-only quantisation in groups, with methods that minimise layer output error such as GPTQ or AWQ', ['weight-only', 'weight only', 'group', 'gptq', 'awq', 'post-training', 'layer', 'error']], ['Outlier weights and activations dominate the error; protect or rescale the important channels', ['outlier', 'important', 'salient', 'rescale', 'channel', 'protect', 'scale']], ['Memory savings let a larger model fit on one GPU and speed up memory-bound decoding', ['memory', 'fit', 'gpu', 'bandwidth', 'decod', 'speed', 'larger']], ['Evaluate carefully on your own tasks, including long context and reasoning, not just perplexity', ['evaluat', 'perplexity', 'task', 'benchmark', 'reasoning', 'long', 'measure']], ['Consider QLoRA or quantisation-aware fine-tuning when accuracy loss is too high', ['qlora', 'fine-tun', 'finetun', 'aware', 'lora', 'recover', 'training']]], model: 'For an LLM, decoding is memory-bound, so I use weight-only quantisation to four bits with small groups of weights sharing a scale. Post-training methods such as GPTQ or AWQ choose the rounding to minimise the error in each layer output, and AWQ protects the most important channels. The main concern is outliers: a few large weights or activation channels can dominate the error, so they need special handling. The benefit is that a much larger model fits on one GPU and decoding is faster. I evaluate on my real tasks, including long context and reasoning, not only perplexity, and use quantisation-aware fine-tuning if quality drops too far.' }
    ]
  },

  {
    id: 'cpp-deploy', title: 'C and C++ model deployment', tracks: ['auto', 'cv', 'mlops', 'mle'],
    tasks: [
      {
        id: 'cpp-tree', title: 'Generate C code from a decision tree',
        prompt: `Small tree models are often shipped as generated C. Write \`tree_to_c(tree)\` that returns C source for a function \`float predict(const float *x)\`.

A node is either a leaf \`{"value": v}\` or a split \`{"feature": i, "threshold": t, "left": node, "right": node}\`, where \`x[i] <= t\` goes left.

Emit exactly this structure (whitespace is not checked):

\`\`\`
float predict(const float *x) {
    if (x[0] <= 2.5f) {
        return 1.0f;
    } else {
        return 0.0f;
    }
}
\`\`\`

Write floats as Python prints them, followed by \`f\`: \`2.5f\`, \`1.0f\`.`,
        starter: R`def tree_to_c(tree):
    pass

print(tree_to_c({"feature": 0, "threshold": 2.5, "left": {"value": 1.0}, "right": {"value": 0.0}}))
`,
        solution: R`def tree_to_c(tree):
    def emit(node, depth):
        pad = "    " * depth
        if "value" in node:
            return [f"{pad}return {float(node['value'])}f;"]
        lines = [f"{pad}if (x[{node['feature']}] <= {float(node['threshold'])}f) {{"]
        lines += emit(node["left"], depth + 1)
        lines.append(f"{pad}}} else {{")
        lines += emit(node["right"], depth + 1)
        lines.append(f"{pad}}}")
        return lines
    return "\n".join(["float predict(const float *x) {"] + emit(tree, 1) + ["}"])
`,
        tests: [
          { name: 'Single split', code: R`out = tree_to_c({"feature": 0, "threshold": 2.5, "left": {"value": 1.0}, "right": {"value": 0.0}})
exp = "float predict(const float *x) { if (x[0] <= 2.5f) { return 1.0f; } else { return 0.0f; } }"
assert " ".join(out.split()) == exp, 'Generated code differs. Got: ' + " ".join(out.split())` },
          { name: 'Leaf only', code: R`out = tree_to_c({"value": 3})
assert " ".join(out.split()) == "float predict(const float *x) { return 3.0f; }", 'A single leaf returns its value; integers print as 3.0f'` },
          { name: 'Nested tree', code: R`t = {"feature": 2, "threshold": 0.5,
     "left": {"feature": 0, "threshold": -1.0, "left": {"value": 0.25}, "right": {"value": 0.75}},
     "right": {"value": 1.0}}
exp = ("float predict(const float *x) { if (x[2] <= 0.5f) { if (x[0] <= -1.0f) { return 0.25f; } else { return 0.75f; } }"
       " else { return 1.0f; } }")
assert " ".join(tree_to_c(t).split()) == exp, 'Nested splits must nest the if/else blocks'` }
        ]
      },
      {
        id: 'cpp-chw', title: 'Preprocess: HWC to CHW',
        prompt: `Cameras and OpenCV give images as height × width × channel (HWC) bytes. Most inference engines want channel-first (CHW) floats. Getting this wrong is the most common C++ deployment bug.

Write \`hwc_to_chw(image, mean, std)\`:

- \`image\`: array of shape \`(H, W, 3)\`, values 0 to 255.
- Scale to 0..1, then normalise each channel: \`(x / 255 - mean[c]) / std[c]\`.
- Return a float32 numpy array of shape \`(3, H, W)\`.`,
        starter: R`import numpy as np

def hwc_to_chw(image, mean, std):
    pass
`,
        solution: R`import numpy as np

def hwc_to_chw(image, mean, std):
    x = np.asarray(image, dtype=np.float32) / 255.0
    x = (x - np.asarray(mean, dtype=np.float32)) / np.asarray(std, dtype=np.float32)
    return np.ascontiguousarray(x.transpose(2, 0, 1), dtype=np.float32)
`,
        tests: [
          { name: 'Shape and type', code: R`import numpy as np
out = hwc_to_chw(np.zeros((4, 6, 3), dtype=np.uint8), [0, 0, 0], [1, 1, 1])
assert out.shape == (3, 4, 6), 'Output shape must be (3, H, W), got ' + str(out.shape)
assert out.dtype == np.float32, 'Output must be float32'` },
          { name: 'Channels end up in the right place', code: R`import numpy as np
img = np.zeros((2, 2, 3), dtype=np.uint8); img[..., 0] = 255; img[..., 2] = 51
out = hwc_to_chw(img, [0, 0, 0], [1, 1, 1])
assert close(out[0], [[1, 1], [1, 1]]) and close(out[1], [[0, 0], [0, 0]]) and close(out[2], [[0.2, 0.2], [0.2, 0.2]], 1e-5), 'Channel 0 should be all 1.0, channel 2 all 0.2'` },
          { name: 'Per-channel normalisation', code: R`import numpy as np
img = np.full((1, 1, 3), 255, dtype=np.uint8)
out = hwc_to_chw(img, [0.5, 0.25, 0.0], [0.5, 0.25, 2.0])
assert close(out.reshape(3), [1.0, 3.0, 0.5], 1e-5), 'Expected [1.0, 3.0, 0.5] for a white pixel'` },
          { name: 'Pixel positions preserved', code: R`import numpy as np
img = np.arange(24, dtype=np.uint8).reshape(2, 4, 3)
out = hwc_to_chw(img, [0, 0, 0], [1, 1, 1])
assert close(out[1, 1, 2] * 255, img[1, 2, 1], 1e-4), 'out[c, h, w] must equal image[h, w, c]'` }
        ]
      }
    ],
    quiz: [
      { q: 'What does RAII give you in C++ inference code?', options: ['Faster maths', 'Resources such as buffers and sessions are released automatically when their owner goes out of scope', 'Automatic GPU use', 'Dynamic typing'], answer: 1, why: 'Tie a resource to an object lifetime: no leaks on early return or exception.', level: 'easy' },
      { q: 'std::unique_ptr versus std::shared_ptr?', options: ['They are the same', 'unique_ptr has one owner and no overhead; shared_ptr is reference-counted for shared ownership', 'shared_ptr is faster', 'unique_ptr can be copied'], answer: 1, why: 'Default to unique_ptr. Use shared_ptr only when ownership is truly shared.', level: 'easy' },
      { q: 'Why avoid heap allocation inside a real-time inference loop?', options: ['It is illegal C++', 'Allocation time is unpredictable and fragments memory; allocate once and reuse buffers', 'The heap is read-only', 'It disables SIMD'], answer: 1, why: 'Pre-allocate input and output tensors at start-up.', level: 'medium' },
      { q: 'Your C++ pipeline gives different predictions from Python on the same image. First suspect?', options: ['The compiler', 'Preprocessing: channel order (BGR or RGB), layout (HWC or CHW), resize method, normalisation', 'The CPU', 'The model weights'], answer: 1, why: 'Dump the preprocessed tensor from both and compare element by element.', level: 'medium' },
      { q: 'What does a parameter of type const Tensor& promise?', options: ['No copy is made and the function will not modify the tensor', 'The tensor is copied and then modified', 'The tensor lives on the GPU', 'The tensor is deleted afterwards'], answer: 0, why: 'A const reference avoids a copy and forbids modification.', level: 'easy' },
      { q: 'ONNX is best described as…', options: ['A C++ compiler', 'A GPU driver', 'An open, framework-neutral format for model graphs and weights', 'A Python web framework'], answer: 2, why: 'It lets you train in one framework and run in another runtime.', level: 'easy' },
      { q: 'A detector in your C++ app labels red cars as blue cars but is otherwise accurate. Likely cause?', options: ['The red and blue channels are swapped: OpenCV’s BGR was not converted to RGB', 'The model is too small', 'The batch size is 1', 'The GPU is too slow'], answer: 0, why: 'A channel-order mismatch swaps colours but keeps the shapes right.', level: 'medium' },
      { q: 'Why is reading a row-major image row by row faster than column by column?', options: ['Columns need more arithmetic', 'Rows are processed by the GPU', 'Consecutive addresses use each loaded cache line fully, while column steps jump across memory', 'Compilers refuse column loops'], answer: 2, why: 'Cache lines are loaded in blocks of neighbouring bytes.', level: 'medium' },
      { q: 'A 1920 × 1080 RGB uint8 frame is converted to float32 CHW. About how large is the float tensor (1 MB = 1,000,000 bytes)?', options: ['6.2 MB', '24.9 MB', '49.8 MB', '8.3 MB'], answer: 1, why: '1920 × 1080 × 3 × 4 bytes is about 24.9 MB, four times the uint8 frame.', level: 'hard' },
      { q: 'You keep float* p = v.data() for a std::vector v, then call v.push_back(x) and read through p. What is the risk?', options: ['p may dangle if push_back reallocated the storage', 'push_back always keeps the same address', 'p becomes const', 'The vector shrinks'], answer: 0, why: 'Growing a vector can move its storage and invalidate pointers into it.', level: 'hard' },
      { q: 'Why can a move constructor that is not marked noexcept slow down std::vector growth?', options: ['It forbids vectors of floats', 'It makes every element 8 bytes', 'It disables inlining', 'The vector may copy elements on reallocation instead of moving them'], answer: 3, why: 'To keep its exception guarantee, vector moves only when the move cannot throw.', level: 'hard' },
      { q: 'The release build crashes but the debug build works, and the compiler shows no warnings. Best first step?', options: ['Raise the optimisation level', 'Delete the failing input', 'Build with AddressSanitizer and UndefinedBehaviorSanitizer, reproduce, and read the first report', 'Add more threads'], answer: 2, why: 'Release-only failures are often undefined behaviour, which sanitizers detect.', level: 'hard' }
    ],
    interview: [
      { q: 'How do you deploy a PyTorch model in a C++ application?', level: 'medium', points: [['Export the model: ONNX or TorchScript', ['onnx', 'torchscript', 'export']], ['Load it with a runtime: ONNX Runtime, TensorRT, LibTorch, OpenVINO', ['onnx runtime', 'tensorrt', 'libtorch', 'openvino', 'runtime']], ['Reimplement preprocessing and postprocessing identically', ['preprocess', 'postprocess', 'normali', 'resize']], ['Verify outputs match Python on the same inputs', ['verif', 'match', 'compare', 'same input', 'parity']], ['Manage memory and threads; measure latency', ['memory', 'thread', 'latency', 'buffer', 'profil']]], model: 'I export the trained model to an exchange format, usually ONNX, with fixed or well-defined dynamic shapes, and check the exported graph in Python first. In C++ I load it with a runtime suited to the target: ONNX Runtime for portability, TensorRT on NVIDIA GPUs, OpenVINO on Intel, or LibTorch if I need TorchScript. I create the session once, allocate input and output buffers once and reuse them. The risky part is preprocessing and postprocessing, which I reimplement in C++ and verify against Python by comparing tensors on the same test images. Finally I profile latency, including the tail, and tune threads and batch size.' },
      { q: 'What C++ features and practices matter most for production inference code?', level: 'medium', points: [['RAII and smart pointers for ownership', ['raii', 'smart pointer', 'unique_ptr', 'ownership']], ['Avoid copies: references, move semantics, spans', ['move', 'reference', 'copy', 'span', 'const']], ['No allocation in the hot loop; reuse buffers', ['alloc', 'reuse', 'pre-alloc', 'buffer']], ['Const correctness, error handling, tests', ['const', 'error', 'test', 'exception']], ['Build and tooling: CMake, sanitizers, static analysis', ['cmake', 'sanitiz', 'static analysis', 'clang-tidy', 'valgrind']]], model: 'Ownership first: every resource, such as a session, buffer or file, is owned by an object and released by its destructor, with unique_ptr as the default smart pointer. Second, avoid needless copies of large tensors by passing const references or views and using move semantics. Third, keep the hot loop free of heap allocation by pre-allocating and reusing buffers, which also keeps timing predictable. I write const-correct interfaces, check every error path, and unit-test pre- and postprocessing against reference data. The build uses CMake with warnings as errors, and I run address and undefined-behaviour sanitizers and static analysis in CI.' },
      { q: 'You converted a Python model to C and the outputs differ slightly. How do you find the cause?', level: 'hard', points: [['Compare intermediate values stage by stage', ['intermediate', 'stage', 'layer by layer', 'step by step']], ['Float precision: float32 versus Python float64', ['float32', 'float64', 'double', 'precision']], ['Operator differences: rounding, resize, padding, maths functions', ['round', 'resize', 'padding', 'operator', 'function']], ['Define a tolerance and automate back-to-back tests', ['tolerance', 'back-to-back', 'automat', 'test vector', 'regression']]], model: 'I run the same input through both and dump intermediate values after each stage: preprocessing, each layer or tree, postprocessing. The first stage that differs beyond tolerance is where to look. Typical causes are Python using 64-bit doubles where C uses 32-bit floats, a different rounding mode, a different resize or padding convention, integer overflow, or a library maths function that differs slightly. Once fixed, I define an acceptable tolerance, or bit-exactness for integer code, and add automated back-to-back tests with recorded test vectors so that any later change is caught.' },
      { q: 'What is ONNX and why is it useful for deployment?', level: 'easy', points: [['An open format for representing a trained model as a graph of operators with weights', ['open', 'format', 'graph', 'operator', 'weights', 'standard']], ['Exported from frameworks such as PyTorch and TensorFlow', ['export', 'pytorch', 'tensorflow', 'framework', 'convert']], ['Runs on many runtimes and hardware backends, decoupling training from deployment', ['runtime', 'backend', 'hardware', 'portable', 'decouple', 'tensorrt', 'openvino', 'onnx runtime']], ['Limits: operator support and opset versions, dynamic shapes; always verify outputs', ['operator', 'opset', 'unsupported', 'dynamic', 'verify', 'limit', 'support']]], model: 'ONNX is an open format that describes a trained model as a graph of standard operators together with its weights. I can export from PyTorch or TensorFlow and then run the same file with ONNX Runtime, TensorRT, OpenVINO or other engines on many kinds of hardware, so training and deployment are decoupled and I am not tied to Python at run time. The limits are that every operator must exist in the chosen opset and in the target runtime, and dynamic shapes or custom operations can cause trouble. So after export I always run the same inputs through the original and the ONNX model and compare the outputs.' },
      { q: 'What is an inference engine, and how does it differ from a training framework?', level: 'easy', points: [['An inference engine only executes a trained model, with no training or gradients', ['execute', 'only', 'inference', 'no training', 'gradient', 'forward']], ['It optimises the graph: fusing operators, constant folding, memory planning', ['optimis', 'optimiz', 'fuse', 'fusion', 'fold', 'memory plan', 'graph']], ['It targets specific hardware with tuned kernels', ['hardware', 'kernel', 'gpu', 'cpu', 'accelerat', 'target', 'tuned']], ['Smaller footprint and lower latency than a full framework; examples are TensorRT and ONNX Runtime', ['footprint', 'latency', 'small', 'tensorrt', 'onnx runtime', 'openvino', 'example', 'light']]], model: 'A training framework such as PyTorch is built for flexibility: it records gradients, supports dynamic control flow and ships with a large library. An inference engine only runs a trained model forward, so it can be much leaner and faster. It optimises the graph by fusing operators, folding constants and planning memory in advance, and it uses kernels tuned for specific hardware, a CPU, a GPU or an accelerator. The result is lower latency and a smaller footprint. Examples are ONNX Runtime, TensorRT and OpenVINO. The trade-off is that I must check that the engine supports all operators in my model.' },
      { q: 'Why would you deploy in C++ rather than Python?', level: 'easy', points: [['Lower overhead and predictable latency, with no interpreter or garbage collector pauses', ['overhead', 'latency', 'interpreter', 'garbage', 'predictable', 'pause', 'fast']], ['Fine control of memory, threads and hardware', ['control', 'memory', 'thread', 'hardware', 'resource']], ['Fits into existing C++ systems, embedded targets and products with small footprint', ['integrat', 'existing', 'embedded', 'footprint', 'product', 'binary', 'dependenc']], ['Cost: slower development, so prototype in Python and port only what is needed', ['slower', 'development', 'prototype', 'python', 'cost', 'port', 'effort', 'complex']]], model: 'The main reasons are control and predictability. C++ has no interpreter or garbage collector, so overhead and latency jitter are lower and memory use is explicit. I can control threads, buffers and the hardware directly. Often the application the model belongs to, such as a vehicle or camera system, is already C++, and a single compiled binary with few dependencies is easier to ship and certify. The price is slower development and more risk of bugs like memory errors. So I prototype and train in Python, and port only the inference path to C++, then verify that it matches the Python results.' },
      { q: 'How do you handle preprocessing correctly when porting a vision model to C++?', level: 'medium', points: [['Reproduce the training preprocessing exactly: resize method, normalisation constants, colour order', ['exact', 'same', 'resize', 'normalis', 'normaliz', 'constant', 'colour', 'color', 'bgr', 'rgb']], ['Match the tensor layout and data type, such as NCHW versus NHWC and float32 versus uint8', ['layout', 'nchw', 'nhwc', 'type', 'float32', 'uint8', 'channel', 'shape']], ['Libraries differ: OpenCV defaults versus the Python image library, interpolation and rounding', ['opencv', 'library', 'interpolation', 'rounding', 'differ', 'pillow', 'default']], ['Test on identical images and compare tensors before and after preprocessing', ['test', 'compare', 'identical', 'tensor', 'golden', 'reference', 'diff']]], model: 'Most porting bugs live in preprocessing, not in the network. I must reproduce exactly what training did: the resize method, the crop, the normalisation mean and standard deviation, and the colour channel order, because OpenCV loads images as BGR while many Python pipelines use RGB. The tensor layout and type must match too, for example channels-first versus channels-last, float versus integer. Different libraries use different interpolation and rounding, so small numerical differences appear. I save reference tensors from the Python pipeline for a set of images, run the C++ code on the same files, and compare element by element against a tolerance.' },
      { q: 'How do you run inference safely from several threads in a C++ service?', level: 'medium', points: [['Know which runtime objects are thread-safe: often a loaded model is shareable, but sessions or contexts are not', ['thread-safe', 'thread safe', 'session', 'context', 'share', 'object', 'documentation']], ['One session or context per thread, or a pool of workers with a request queue', ['pool', 'queue', 'per thread', 'worker', 'instance', 'session']], ['Avoid contention and false sharing: preallocate buffers per worker and avoid locks in the hot path', ['contention', 'lock', 'preallocate', 'buffer', 'hot', 'mutex', 'false sharing']], ['Tune intra-op and inter-op threads to the CPU cores and test under load', ['core', 'intra', 'inter', 'tune', 'load', 'oversubscri', 'test', 'benchmark']]], model: 'First I check the runtime documentation to see what is thread-safe. Often the loaded model is shared read-only, but each inference session or execution context holds mutable buffers and must not be used by two threads at once. A common design is a pool of worker threads, each with its own session and preallocated buffers, fed by a request queue, so there is no locking in the hot path. I also tune the runtime threads against the number of cores, because many workers each spawning many threads oversubscribe the CPU and hurt latency. Then I load test with realistic concurrency and watch throughput and tail latency.' },
      { q: 'Your C++ inference service has good average latency but occasional slow requests at the 99th percentile. How do you find the cause?', level: 'hard', points: [['Measure percentiles and trace each stage to see which stage spikes', ['percentile', 'p99', 'trace', 'stage', 'measure', 'profile', 'timing']], ['Memory allocation or first-call initialisation in the hot path', ['alloc', 'memory', 'initialis', 'initializ', 'first call', 'warm-up', 'warm up', 'lazy']], ['Contention: locks, thread oversubscription, queueing, or other processes and CPU frequency scaling', ['contention', 'lock', 'oversubscri', 'queue', 'frequency', 'scheduler', 'noisy', 'cpu']], ['Input-dependent costs or garbage such as large images, dynamic shapes, retries', ['input', 'dynamic shape', 'large', 'retry', 'size', 'dependent']], ['Fix with preallocation, warm-up, pinning threads and limits, then re-measure', ['preallocat', 'warm', 'pin', 'affinity', 'limit', 're-measure', 'remeasure', 'fix']]], model: 'Averages hide this, so I record per-stage timings for every request and look at the slow ones specifically. Common causes: memory allocation inside the hot loop, lazy initialisation on the first call or on a new input shape, lock contention, or too many threads fighting for cores. Other processes, CPU frequency scaling and the operating system scheduler can also cause jitter. Some slowness is input-dependent, for example very large images or dynamic shapes that trigger re-planning. Then I fix: preallocate and reuse buffers, warm up the model, pin threads, bound queue lengths and input sizes. After each fix I measure the 99th percentile again under realistic load.' },
      { q: 'The ONNX export fails or the target runtime does not support an operator in your model. What do you do?', level: 'hard', points: [['Read the error to find the exact operator and check the opset version and runtime support', ['error', 'operator', 'opset', 'version', 'support', 'identify', 'read']], ['Replace it with an equivalent supported composition of operators, or change the model code', ['replace', 'rewrite', 'equivalent', 'compos', 'change', 'modify', 'supported']], ['Implement a custom operator or fall back to a partial graph on another backend', ['custom', 'plugin', 'fall back', 'fallback', 'partition', 'backend']], ['Verify numerically that the modified model matches the original and keeps its accuracy', ['verify', 'numeric', 'match', 'accuracy', 'compare', 'test', 'tolerance']]], model: 'First I identify exactly which operator or construct fails, then check whether a newer opset or a newer runtime version supports it. If not, I rewrite that part of the model using supported operators, for example replacing an exotic activation or a dynamic indexing pattern with an equivalent form, and I may need to fix input shapes to be static. As a last resort I write a custom operator or plugin, or split the graph so the unsupported part runs on a different backend. After any change I confirm numerically that outputs match the original model within tolerance and that accuracy on the evaluation set is unchanged.' }
    ]
  },

  {
    id: 'cuda-gpu', title: 'GPU and CUDA fundamentals', tracks: ['mle', 'cv', 'mlops', 'auto', 'genai'],
    tasks: [
      {
        id: 'gpu-index', title: 'Blocks, threads and the global index',
        prompt: `A CUDA kernel runs on a grid of blocks, each with the same number of threads. To process an array of \`n\` elements with one thread each:

- \`num_blocks(n, threads_per_block)\`: the number of blocks needed (round up).
- \`global_index(block_idx, block_dim, thread_idx)\`: the array index a thread works on, \`block_idx * block_dim + thread_idx\`.
- \`active(block_idx, block_dim, thread_idx, n)\`: \`True\` if that index is inside the array. Threads beyond \`n\` must do nothing.`,
        starter: R`def num_blocks(n, threads_per_block):
    pass

def global_index(block_idx, block_dim, thread_idx):
    pass

def active(block_idx, block_dim, thread_idx, n):
    pass
`,
        solution: R`def num_blocks(n, threads_per_block):
    return (n + threads_per_block - 1) // threads_per_block

def global_index(block_idx, block_dim, thread_idx):
    return block_idx * block_dim + thread_idx

def active(block_idx, block_dim, thread_idx, n):
    return global_index(block_idx, block_dim, thread_idx) < n
`,
        tests: [
          { name: 'Number of blocks rounds up', code: R`assert num_blocks(1000, 256) == 4 and num_blocks(1024, 256) == 4 and num_blocks(1025, 256) == 5 and num_blocks(1, 256) == 1, 'Use ceiling division: 1000 elements with 256 threads per block need 4 blocks'` },
          { name: 'Global index', code: R`assert global_index(0, 256, 5) == 5 and global_index(3, 256, 10) == 778, 'index = block_idx * block_dim + thread_idx'` },
          { name: 'Bounds check', code: R`assert active(3, 256, 231, 1000) is True and active(3, 256, 232, 1000) is False, 'With n = 1000 the last valid index is 999; thread 232 of block 3 is index 1000'` },
          { name: 'Every element covered exactly once', code: R`n, tpb = 1000, 256
seen = [global_index(b, tpb, t) for b in range(num_blocks(n, tpb)) for t in range(tpb) if active(b, tpb, t, n)]
assert sorted(seen) == list(range(n)), 'Active threads must cover indices 0..n-1 exactly once'` }
        ]
      },
      {
        id: 'gpu-amdahl', title: "Amdahl's law",
        prompt: `Only part of a program can be parallelised. Write \`amdahl(p, n)\`: the overall speed-up when a fraction \`p\` of the run time is sped up \`n\` times.

\`speedup = 1 / ((1 - p) + p / n)\``,
        starter: R`def amdahl(p, n):
    pass

print(amdahl(0.9, 10))  # about 5.26
`,
        solution: R`def amdahl(p, n):
    return 1.0 / ((1.0 - p) + p / n)
`,
        tests: [
          { name: 'Typical case', code: R`assert close(amdahl(0.9, 10), 1 / 0.19), '90% parallel with 10x speed-up gives about 5.26x'` },
          { name: 'Fully parallel and fully serial', code: R`assert close(amdahl(1.0, 8), 8.0) and close(amdahl(0.0, 100), 1.0), 'p = 1 gives n; p = 0 gives 1'` },
          { name: 'The serial part sets the limit', code: R`assert amdahl(0.9, 1e9) < 10.0001 and amdahl(0.9, 1e9) > 9.99, 'With 10% serial work the speed-up can never exceed 10x'` }
        ]
      }
    ],
    quiz: [
      { q: 'Why are GPUs faster than CPUs for neural networks?', options: ['Higher clock speed', 'Thousands of cores run the same simple operation on many data elements in parallel', 'They have more RAM', 'They use Python'], answer: 1, why: 'Matrix multiplication and convolution are data-parallel, which fits the GPU design.', level: 'easy' },
      { q: 'Your GPU utilisation is 30% during training. Most likely bottleneck?', options: ['The GPU is broken', 'Data loading and preprocessing on the CPU', 'Too many parameters', 'The loss function'], answer: 1, why: 'More loader workers, pinned memory, caching or GPU-side augmentation usually help.', level: 'medium' },
      { q: 'Why is copying data between CPU and GPU expensive?', options: ['It is encrypted', 'They have separate memories; each transfer crosses the bus and can stall the pipeline', 'CPUs are 8-bit', 'It is free'], answer: 1, why: 'Keep tensors on the device, batch transfers and avoid calling .cpu() or .item() inside hot loops.', level: 'easy' },
      { q: 'What does mixed-precision (FP16) inference or training give?', options: ['Higher accuracy', 'About half the memory and faster maths on modern GPUs, with small numerical risk', 'Larger models', 'Slower training'], answer: 1, why: 'Use automatic mixed precision; a gradient scaler prevents underflow during training.', level: 'medium' },
      { q: 'In CUDA, a kernel is…', options: ['A function launched from the host and run by many GPU threads in parallel', 'The operating system core', 'A type of GPU memory', 'A compression format'], answer: 0, why: 'You launch it with a grid of blocks of threads.', level: 'easy' },
      { q: 'On NVIDIA GPUs, a warp is…', options: ['A block of 1024 threads', 'A GPU driver', 'A group of 32 threads that execute together', 'A kind of memory'], answer: 2, why: 'Threads of a warp follow the same instruction at the same time.', level: 'easy' },
      { q: 'A kernel is launched with 3 blocks of 128 threads for 400 elements. What happens?', options: ['All elements are processed', 'The kernel crashes at launch', 'Threads wrap around and process some elements twice', 'Only 384 elements are covered, so the last 16 are never processed'], answer: 3, why: '3 × 128 = 384, which is fewer than 400; round the block count up.', level: 'medium' },
      { q: 'A job must score a million images overnight, and nobody waits for individual results. Which batch setting suits it?', options: ['A large batch that maximises throughput', 'Batch size 1 to minimise latency', 'No batching at all', 'Random batch sizes'], answer: 0, why: 'When latency does not matter, big batches use the GPU best.', level: 'medium' },
      { q: '80% of a program is parallelised and sped up 4 times. What is the overall speed-up (Amdahl’s law)?', options: ['3.2×', '4×', '2.5×', '1.25×'], answer: 2, why: '1 / (0.2 + 0.8 / 4) = 1 / 0.4 = 2.5.', level: 'hard' },
      { q: 'Your timer says one forward pass takes 0.2 ms, yet the end-to-end loop is far slower. What is the likely measurement error?', options: ['The GPU clock runs backwards', 'The clock was read without synchronising, so only the launch was timed', 'Python rounds times down', 'The model has no layers'], answer: 1, why: 'GPU calls return immediately; synchronise before reading the clock.', level: 'hard' },
      { q: 'Threads of one warp take different sides of an if/else. What is the effect?', options: ['The GPU picks the faster branch', 'The kernel fails to compile', 'Half the threads are deleted', 'Both paths run one after another with some threads idle, so time is lost'], answer: 3, why: 'This is warp divergence.', level: 'hard' },
      { q: 'You need an effective batch of 64 but only 16 samples fit in GPU memory. What do you do?', options: ['Move the model to the CPU', 'Train for four times as many epochs', 'Accumulate gradients over 4 batches of 16 before each optimiser step', 'Use batch size 1'], answer: 2, why: 'Gradient accumulation gives the same effective batch with less memory.', level: 'hard' }
    ],
    interview: [
      { q: 'Explain the CUDA execution model: kernels, threads, blocks and grids.', level: 'easy', points: [['A kernel is a function executed by many GPU threads in parallel', ['kernel']], ['Threads are grouped into blocks, blocks into a grid', ['block', 'grid']], ['Each thread computes its own index and processes its element', ['index', 'element', 'blockidx', 'threadidx']], ['Host and device have separate memory; data must be copied', ['host', 'device', 'copy', 'transfer', 'memory']]], model: 'In CUDA the CPU is the host and the GPU is the device, each with its own memory. A kernel is a function that the host launches on the device, where it is executed by many threads at once. Threads are organised into blocks, and blocks into a grid. Each thread reads its block index and thread index, computes a global index and works on that element, with a bounds check because the grid is usually rounded up beyond the data size. Threads in a block can share fast shared memory and synchronise. A typical program allocates device memory, copies inputs to it, launches kernels and copies results back, trying to minimise those transfers.' },
      { q: 'Inference on the GPU is slower than you expected. What do you check?', level: 'medium', points: [['Measure correctly: warm-up and synchronise before timing', ['warm', 'synchroni', 'measure', 'profil']], ['CPU-side bottlenecks: preprocessing, data transfer', ['preprocess', 'transfer', 'cpu', 'copy']], ['Batch size and throughput versus latency', ['batch']], ['Optimised runtime and precision: TensorRT, FP16 or INT8', ['tensorrt', 'fp16', 'int8', 'half', 'onnx', 'quanti']], ['Memory: avoid reallocations and host-device ping-pong', ['memory', 'alloc', 'pinned']]], model: 'First I make sure I am measuring correctly: GPU calls are asynchronous, so I warm up and synchronise before reading the clock, and I use a profiler to split time between preprocessing, transfer, inference and postprocessing. Often the model is fast and the CPU work around it is slow. Then I look at batch size, since a larger batch raises throughput at the cost of latency. I export the model to an optimised engine such as TensorRT, enable FP16 or INT8, and fix input shapes where possible. I avoid repeated allocations and unnecessary copies between host and device, use pinned memory for transfers, and move preprocessing to the GPU if it dominates.' },
      { q: 'You run out of GPU memory during training. What are your options?', level: 'medium', points: [['Smaller batch with gradient accumulation', ['batch', 'accumulat']], ['Mixed precision', ['mixed precision', 'fp16', 'half', 'amp']], ['Gradient checkpointing or a smaller model or input', ['checkpoint', 'smaller', 'resolution', 'sequence length']], ['Free what you do not need: no_grad for evaluation, do not keep graph references', ['no_grad', 'detach', 'release', 'graph', 'eval']]], model: 'The quickest fix is a smaller batch size, with gradient accumulation to keep the effective batch the same. Mixed precision roughly halves activation memory. Gradient checkpointing trades compute for memory by recomputing activations in the backward pass. I can also reduce input resolution or sequence length, or use a smaller model or parameter-efficient fine-tuning. I check for avoidable waste: evaluation without no_grad, storing the loss tensor with its graph instead of a plain number, or keeping large tensors alive. If it still does not fit, I move to multiple GPUs or a larger instance.' },
      { q: 'Why are GPUs well suited to deep learning compared with CPUs?', level: 'easy', points: [['Thousands of simple cores do many operations in parallel', ['thousand', 'core', 'parallel', 'many', 'simultaneous', 'throughput']], ['Neural network workloads are dominated by matrix multiplications, which parallelise naturally', ['matrix', 'multiplic', 'tensor', 'parallelis', 'paralleliz', 'linear algebra']], ['High memory bandwidth and dedicated tensor units', ['bandwidth', 'memory', 'tensor core', 'tensor unit', 'special']], ['CPUs are better at serial, branchy logic and low-latency single tasks; a GPU needs enough work to stay busy', ['serial', 'branch', 'latency', 'single', 'enough work', 'busy', 'cpu']]], model: 'A neural network is mostly matrix multiplications and element-wise operations on large arrays, and those split into thousands of independent pieces. A GPU has thousands of simple cores and very high memory bandwidth, plus dedicated tensor units for low-precision matrix maths, so it delivers much higher throughput than a CPU on this kind of work. A CPU has a few powerful cores that are better at serial, branching logic and low latency for a single task. So a GPU wins when there is a lot of parallel work, but for tiny inputs the transfer and launch overhead can make the CPU faster.' },
      { q: 'Describe the GPU memory hierarchy and why it matters for performance.', level: 'easy', points: [['Registers are the fastest and private to each thread', ['register', 'fastest', 'private', 'thread']], ['Shared memory is fast, on-chip and shared within a block, managed by the programmer', ['shared', 'on-chip', 'on chip', 'block', 'programmer', 'manual', 'cache']], ['Global memory is large but slow, with high latency; caches sit between', ['global', 'large', 'slow', 'latency', 'dram', 'hbm', 'cache', 'l2']], ['Performance often depends on reducing global memory traffic and reusing data in fast memory', ['reuse', 'traffic', 'access', 'bandwidth', 'reduce', 'tiling', 'coalesc']]], model: 'From fastest to slowest: registers are private to each thread, shared memory is a small on-chip memory shared by the threads of a block and managed explicitly by the programmer, and global memory is the large off-chip memory that every thread can reach but with high latency, with caches in between. Many GPU workloads are limited by memory traffic rather than arithmetic, so a good kernel reads from global memory in a coalesced pattern, loads a tile of data into shared memory once, and reuses it many times from there. Understanding this hierarchy is the key to making kernels fast.' },
      { q: 'What is a warp, and what is warp divergence?', level: 'medium', points: [['A warp is a group of 32 threads that execute the same instruction together', ['warp', '32', 'thirty-two', 'group', 'same instruction', 'lockstep', 'simt']], ['If threads in a warp take different branches, the paths execute one after the other', ['branch', 'different', 'path', 'serial', 'if', 'one after', 'divergen']], ['This wastes cycles because some threads are idle while others run', ['idle', 'waste', 'mask', 'inactive', 'slow', 'throughput']], ['Reduce it by making branches depend on warp-uniform conditions, reorganising data and avoiding thread-dependent control flow', ['uniform', 'reorganis', 'reorganiz', 'avoid', 'sort', 'predication', 'data layout', 'rearrange']]], model: 'A warp is a group of 32 threads that the hardware schedules together and that execute the same instruction at the same time. If the threads of one warp meet an if statement and some go one way and some the other, the warp runs both paths one after another, with the threads that do not take a path switched off. That is warp divergence, and it wastes cycles because part of the warp sits idle. To reduce it I make the branch condition the same across a warp where possible, reorganise the data so similar items are processed together, or replace branches with arithmetic.' },
      { q: 'What does it mean for a GPU kernel to be memory-bound or compute-bound?', level: 'medium', points: [['Compute-bound: limited by arithmetic throughput; memory-bound: limited by how fast data can be moved', ['arithmetic', 'compute', 'memory', 'bandwidth', 'limited', 'throughput', 'data']], ['Arithmetic intensity: operations per byte moved decides which', ['intensity', 'per byte', 'ratio', 'flops', 'operations']], ['Roofline model compares a kernel against the hardware compute peak and the memory bandwidth peak', ['roofline', 'peak', 'bandwidth', 'ceiling', 'model']], ['Optimise accordingly: reduce memory traffic or fuse operations if memory-bound; use tensor cores or lower precision if compute-bound', ['fuse', 'fusion', 'tensor core', 'precision', 'reduce', 'optimis', 'optimiz', 'traffic']]], model: 'Every kernel does some arithmetic and moves some bytes. The ratio, the arithmetic intensity, tells me what limits it. If there are many operations per byte, as in a large matrix multiplication, the kernel is compute-bound and the arithmetic units are the bottleneck. If there are few, like an element-wise addition or a layer normalisation, it is memory-bound and waits for data. The roofline model plots this against the hardware peaks. The optimisation differs: for memory-bound work I reduce traffic, for example by fusing operations so data is read once, and for compute-bound work I use tensor cores and lower precision.' },
      { q: 'How do you profile a slow GPU workload, and what do you look for?', level: 'hard', points: [['Use a profiler: timeline for gaps and kernel durations, then detailed kernel metrics', ['profiler', 'nsight', 'timeline', 'trace', 'kernel', 'metric', 'tool']], ['Look for idle GPU gaps from the CPU, data loading, synchronisation or many tiny kernels', ['gap', 'idle', 'cpu', 'data loading', 'synchron', 'small kernel', 'launch', 'overhead']], ['For heavy kernels check occupancy, memory throughput, achieved versus peak compute', ['occupancy', 'throughput', 'achieved', 'peak', 'bandwidth', 'utilis', 'utiliz']], ['Fix the biggest bottleneck first: batching, fusion, mixed precision, overlapping copies with compute', ['batch', 'fusion', 'fuse', 'mixed precision', 'overlap', 'stream', 'copy', 'biggest']]], model: 'I never guess. I start with a timeline profile of a few iterations to see the big picture: is the GPU busy, or are there gaps where it waits for the CPU, the data loader, host-device copies or synchronisation? Many tiny kernels with launch overhead show up here too. Then, for the heaviest kernels, I use a detailed profiler to see achieved memory throughput and compute against the hardware peaks, plus occupancy, which tells me whether the kernel is memory-bound or compute-bound. I fix the largest bottleneck first, for example with bigger batches, kernel fusion, mixed precision, or overlapping data transfers with compute using streams, and then profile again.' },
      { q: 'Explain coalesced memory access and how shared-memory tiling speeds up a matrix multiplication kernel.', level: 'hard', points: [['Coalescing: neighbouring threads in a warp read neighbouring addresses so the hardware merges them into few transactions', ['coalesc', 'neighbour', 'neighbor', 'adjacent', 'consecutive', 'warp', 'transaction', 'contiguous']], ['Naive matrix multiply reads each element from global memory many times', ['naive', 'global', 'many times', 'repeated', 'redundant', 'each element']], ['Tiling: a block loads a tile of each matrix into shared memory once, and threads reuse it', ['tile', 'tiling', 'shared memory', 'block', 'reuse', 'load once']], ['Synchronise threads between loading and using the tile; avoid bank conflicts', ['synchron', 'syncthreads', 'barrier', 'bank conflict', 'conflict']], ['This raises arithmetic intensity so the kernel gets closer to compute-bound', ['arithmetic intensity', 'compute-bound', 'compute bound', 'faster', 'bandwidth', 'reduce traffic']]], model: 'Coalesced access means that the threads of a warp read consecutive addresses, so the hardware combines them into a few wide memory transactions instead of many. In a naive matrix multiply, every thread reads a row and a column straight from global memory, so each element is fetched many times. With tiling, a thread block cooperatively loads a small tile of each input matrix into shared memory, using coalesced reads, synchronises, and then every thread computes its partial result from the fast shared copy before moving to the next tile. That cuts global memory traffic by roughly the tile width, raising arithmetic intensity so the kernel gets much closer to the compute limit.' },
      { q: 'Compare data parallelism, tensor parallelism and pipeline parallelism for multi-GPU training.', level: 'hard', points: [['Data parallel: each GPU holds a full model copy and processes different data, then gradients are averaged', ['data parallel', 'copy', 'replica', 'gradient', 'average', 'all-reduce', 'all reduce', 'batch']], ['Tensor parallel: split individual layers or matrices across GPUs; needs fast interconnect', ['tensor', 'split', 'layer', 'matrix', 'interconnect', 'nvlink', 'within']], ['Pipeline parallel: put different layers on different GPUs and stream micro-batches, with bubbles', ['pipeline', 'stage', 'micro-batch', 'microbatch', 'bubble', 'layers']], ['Choose by model size and hardware; combine them, and use sharding such as ZeRO or FSDP to save memory', ['combine', 'shard', 'zero', 'fsdp', 'memory', 'model size', 'hybrid', '3d']]], model: 'In data parallelism every GPU holds a full copy of the model and processes a different slice of the batch, then gradients are averaged with an all-reduce. It is simple and scales well as long as the model fits in one GPU. When it does not fit, I split the model. Tensor parallelism splits the individual matrices of a layer across GPUs, which needs very fast links and is used within a node. Pipeline parallelism assigns consecutive groups of layers to different GPUs and streams micro-batches through, at the cost of idle bubbles. Large trainings combine them, and sharding methods spread optimiser state and weights to save memory.' }
    ]
  },

  {
    id: 'ecu-deploy', title: 'ECU and automotive software deployment', tracks: ['auto', 'mlops'],
    tasks: [
      {
        id: 'ecu-can', title: 'Decode a CAN signal',
        prompt: `ECUs exchange data in CAN frames of up to 8 bytes. A signal is a group of bits with a scale and an offset.

Write \`decode_signal(data, start_bit, length, scale, offset, signed=False)\` for little-endian (Intel) signals:

1. Treat \`data\` (a list of byte values) as one little-endian integer.
2. \`raw = (value >> start_bit) & ((1 << length) - 1)\`
3. If \`signed\` and the top bit of \`raw\` is set, subtract \`1 << length\` (two's complement).
4. Return \`raw * scale + offset\`.`,
        starter: R`def decode_signal(data, start_bit, length, scale, offset, signed=False):
    pass

print(decode_signal([0x10, 0x27, 0, 0, 0, 0, 0, 0], 0, 16, 0.01, 0))  # 100.0
`,
        solution: R`def decode_signal(data, start_bit, length, scale, offset, signed=False):
    value = int.from_bytes(bytes(data), "little")
    raw = (value >> start_bit) & ((1 << length) - 1)
    if signed and raw & (1 << (length - 1)):
        raw -= 1 << length
    return raw * scale + offset
`,
        tests: [
          { name: '16-bit speed signal', code: R`assert close(decode_signal([0x10, 0x27, 0, 0, 0, 0, 0, 0], 0, 16, 0.01, 0), 100.0), '0x2710 = 10000, times 0.01 = 100.0'` },
          { name: 'Signal in the second byte', code: R`assert close(decode_signal([0x10, 0x27, 0, 0], 8, 8, 1, 0), 39), 'Bits 8..15 are the second byte: 0x27 = 39'` },
          { name: 'Scale and offset', code: R`assert close(decode_signal([0x64], 0, 8, 0.5, -40), 10.0), 'Raw 100 * 0.5 - 40 = 10 (a typical temperature encoding)'` },
          { name: 'Signed value', code: R`assert close(decode_signal([0xFF], 0, 8, 1, 0, signed=True), -1) and close(decode_signal([0xFF], 0, 8, 1, 0), 255), '0xFF is -1 when signed and 255 when unsigned'` },
          { name: 'Signal across a byte boundary', code: R`assert close(decode_signal([0xF0, 0x0A], 4, 8, 1, 0), 0xAF), 'Bits 4..11 of 0x0AF0 are 0xAF = 175'` }
        ]
      },
      {
        id: 'ecu-ring', title: 'Fixed-memory moving average',
        prompt: `Embedded code cannot grow lists for ever. Write a class \`MovingAverage(size)\` with a method \`update(x)\` that returns the average of the last \`size\` values seen (or of all values so far, if fewer).

Use a fixed-size ring buffer and a running sum: each update must be O(1) and must not allocate.`,
        starter: R`class MovingAverage:
    def __init__(self, size):
        pass

    def update(self, x):
        pass

m = MovingAverage(3)
print([m.update(v) for v in [3, 6, 9, 12]])  # [3.0, 4.5, 6.0, 9.0]
`,
        solution: R`class MovingAverage:
    def __init__(self, size):
        self.buf = [0.0] * size
        self.size = size
        self.count = 0
        self.head = 0
        self.total = 0.0

    def update(self, x):
        if self.count == self.size:
            self.total -= self.buf[self.head]
        else:
            self.count += 1
        self.buf[self.head] = x
        self.total += x
        self.head = (self.head + 1) % self.size
        return self.total / self.count
`,
        tests: [
          { name: 'Warm-up then steady state', code: R`m = MovingAverage(3)
assert close([m.update(v) for v in [3, 6, 9, 12]], [3.0, 4.5, 6.0, 9.0]), 'Expected [3.0, 4.5, 6.0, 9.0]'` },
          { name: 'Window of one', code: R`m = MovingAverage(1)
assert close([m.update(v) for v in [5, 7, -2]], [5, 7, -2]), 'With size 1 the average is the latest value'` },
          { name: 'Long run stays correct', code: R`m = MovingAverage(4)
out = [m.update(v) for v in range(1000)]
assert close(out[-1], (996 + 997 + 998 + 999) / 4), 'After many updates the average must cover only the last 4 values'` },
          { name: 'Independent instances', code: R`a, b = MovingAverage(2), MovingAverage(2)
a.update(10); a.update(20)
assert close(b.update(1), 1.0), 'Two filters must not share state'` }
        ]
      }
    ],
    quiz: [
      { q: 'AUTOSAR Classic versus AUTOSAR Adaptive?', options: ['They are the same', 'Classic: static, real-time software on microcontrollers. Adaptive: service-oriented, POSIX-based, for high-performance computers', 'Adaptive is older', 'Classic runs only on Linux'], answer: 1, why: 'Perception networks usually run on Adaptive-class or Linux/QNX computers; small models can run on Classic ECUs.', level: 'easy' },
      { q: 'What is the difference between MIL, SIL, PIL and HIL testing?', options: ['They test four different cars', 'Model, software, processor and hardware in the loop: each step brings the test closer to the real ECU', 'They are coding standards', 'They are CAN message types'], answer: 1, why: 'MIL tests the model, SIL the compiled code on a PC, PIL the code on the target processor, HIL the real ECU with simulated surroundings.', level: 'medium' },
      { q: 'Why does MISRA C restrict dynamic memory allocation?', options: ['malloc is slow on PCs', 'To avoid fragmentation, leaks and unpredictable timing in safety-related code', 'It saves flash', 'C does not support it'], answer: 1, why: 'Memory is allocated statically so behaviour is deterministic and analysable.', level: 'medium' },
      { q: 'ASIL in ISO 26262 describes…', options: ['The CPU speed', 'The required safety integrity level of a function, from A (lowest) to D (highest)', 'The size of the flash', 'A bus protocol'], answer: 1, why: 'It is derived from severity, exposure and controllability, and sets how rigorous development must be.', level: 'easy' },
      { q: 'ECU stands for…', options: ['Engine Cooling Unit', 'Electronic Control Unit', 'External Computing Utility', 'Embedded Cable Unit'], answer: 1, why: 'A car has dozens of them.', level: 'easy' },
      { q: 'What does a DBC file describe?', options: ['The layout of signals in CAN messages: start bit, length, scale and offset', 'The wiring harness colours', 'The ECU flash map', 'The test report'], answer: 0, why: 'Tools use it to decode raw frames into physical values.', level: 'easy' },
      { q: 'What is the purpose of a watchdog in an ECU?', options: ['Increase the CAN speed', 'Store the model', 'Detect that the software has stopped running normally and trigger a reset or safe state', 'Encrypt messages'], answer: 2, why: 'The software must keep servicing it in time.', level: 'medium' },
      { q: 'Three cyclic tasks need 1 ms every 5 ms, 2 ms every 10 ms and 3 ms every 20 ms. What is the CPU utilisation?', options: ['45%', '65%', '100%', '55%'], answer: 3, why: '0.2 + 0.2 + 0.15 = 0.55.', level: 'medium' },
      { q: 'A moving average sums 8 samples of an unsigned 16-bit signal (maximum 65535). What type must the running sum have?', options: ['16-bit unsigned', '8-bit unsigned', 'At least 32-bit unsigned', '16-bit signed'], answer: 2, why: '8 × 65535 = 524,280, which does not fit in 16 bits.', level: 'hard' },
      { q: 'A 10-bit unsigned signal has scale 0.25 and offset -20. The raw value is 1023. What is the physical value?', options: ['255.75', '235.75', '-20.25', '1003'], answer: 1, why: '1023 × 0.25 = 255.75, and 255.75 - 20 = 235.75.', level: 'hard' },
      { q: 'Which test level shows timing problems caused by the real processor’s pipeline and caches before a full vehicle exists?', options: ['Model-in-the-loop', 'Code review', 'Software-in-the-loop on a PC', 'Processor-in-the-loop on the target processor'], answer: 3, why: 'Only the real processor shows its true timing and numerics.', level: 'hard' },
      { q: 'On a microcontroller without a floating-point unit, why is float arithmetic costly?', options: ['Operations are emulated in software, so they are slower and add code to flash', 'Floats are not allowed in C', 'Floats need more RAM than integers of the same size', 'It disables interrupts'], answer: 0, why: 'Fixed-point integer arithmetic maps directly onto the hardware.', level: 'hard' }
    ],
    interview: [
      { q: 'Walk me through deploying an ML model on an automotive ECU.', level: 'hard', points: [['Requirements and constraints: memory, timing, safety level', ['requirement', 'constraint', 'memory', 'timing', 'asil', 'safety']], ['Shrink the model: small architecture, quantisation, fixed point', ['quanti', 'fixed', 'small', 'prun']], ['Generate or write C code that meets the coding standard', ['c code', 'misra', 'generat', 'autosar']], ['Verify: back-to-back tests, SIL, PIL, HIL', ['back-to-back', 'sil', 'hil', 'pil', 'verif']], ['Integrate with the software architecture and measure on target', ['integrat', 'wcet', 'on target', 'measure', 'runnable', 'component']]], model: 'I start from the requirements: what the function must do, its safety level, and the budget for flash, RAM and execution time on the chosen microcontroller. I design or shrink the model to fit, using a small architecture, quantisation and, if there is no floating-point unit, fixed-point arithmetic. I convert it to C that complies with the project coding standard, either generated or hand-written, and wrap it as a software component in the architecture, for example an AUTOSAR runnable with defined inputs and outputs. Verification goes step by step: back-to-back comparison with the Python reference, software-in-the-loop on a PC, processor-in-the-loop for timing and numerics, then hardware-in-the-loop and vehicle tests. I measure worst-case execution time and stack use on the target, and document everything with traceability to the requirements.' },
      { q: 'How do you test software that will run in a car before the car exists?', level: 'medium', points: [['Model-in-the-loop and software-in-the-loop on a PC', ['mil', 'sil', 'model-in-the-loop', 'software-in-the-loop', 'simulation']], ['Recorded data replay (re-simulation)', ['record', 'replay', 'resim', 're-sim', 'log']], ['Hardware-in-the-loop with simulated sensors and bus', ['hil', 'hardware-in-the-loop', 'simulated']], ['Unit and integration tests with traceability to requirements', ['unit test', 'integration', 'traceab', 'requirement', 'coverage']]], model: 'We climb a ladder of test environments. First the algorithm is tested as a model, and then the compiled code runs on a PC in software-in-the-loop, fed by simulation or by replaying recorded sensor data, which lets us run thousands of scenarios overnight. Processor-in-the-loop runs the same code on the target processor to check timing and numerical behaviour. Hardware-in-the-loop connects the real ECU to a simulator that emulates sensors, actuators and bus traffic, including fault injection. At every level there are unit and integration tests traced to requirements, with coverage measured. Only then do we go to test tracks and public roads.' },
      { q: 'What changes when your Python prototype has to become safety-related embedded code?', level: 'hard', points: [['Determinism: static memory, bounded loops, no recursion', ['static', 'determin', 'bounded', 'no dynamic', 'recursion']], ['Coding and process standards: MISRA, ASPICE, ISO 26262', ['misra', 'aspice', '26262']], ['Numerics: fixed point, overflow, saturation', ['fixed', 'overflow', 'saturat']], ['Verification effort: reviews, coverage, traceability', ['review', 'coverage', 'traceab', 'verif']], ['Fault handling and safe states', ['fault', 'safe state', 'fallback', 'plausib', 'monitor']]], model: 'Almost everything around the algorithm changes. The code must be deterministic: statically allocated memory, bounded loops, no recursion, and a known worst-case execution time. It follows a coding standard such as MISRA C and a process such as Automotive SPICE, with requirements traced to design, code and tests. Numerics need care: fixed-point scaling, overflow and saturation are designed explicitly. Verification is far heavier, with reviews, static analysis, structural coverage and back-to-back tests against the reference. And the function must handle faults: plausibility checks on inputs, monitoring of the model output, and a defined safe state when something is wrong.' },
      { q: 'What is an ECU?', level: 'easy', points: [['An electronic control unit: an embedded computer in a vehicle that controls a function', ['electronic control unit', 'embedded', 'computer', 'control', 'function', 'vehicle']], ['It has a microcontroller or processor, memory, inputs from sensors and outputs to actuators', ['microcontroller', 'processor', 'memory', 'sensor', 'actuator', 'input', 'output']], ['ECUs communicate over in-vehicle networks such as CAN or Ethernet', ['can', 'ethernet', 'network', 'bus', 'lin', 'flexray', 'communicat']], ['Modern cars have many, with real-time and safety requirements; some are powerful domain or central computers', ['many', 'real-time', 'real time', 'safety', 'domain', 'central', 'zonal', 'powerful']]], model: 'An ECU, or electronic control unit, is a small embedded computer in a vehicle that is responsible for a function, such as the engine, the brakes, a door or a camera system. It contains a microcontroller or processor with limited memory, reads sensors, runs software and drives actuators. ECUs talk to each other over in-vehicle networks like CAN and automotive Ethernet. A modern car contains many, and they run under real-time and safety requirements, so the software must be deterministic and thoroughly tested. Newer architectures also include powerful domain or central computers that combine many functions, which is where heavier machine learning models run.' },
      { q: 'What do MIL, SIL, PIL and HIL mean?', level: 'easy', points: [['Model-in-the-loop: test the algorithm model in simulation', ['model-in-the-loop', 'model in the loop', 'mil', 'model', 'simulation']], ['Software-in-the-loop: run the generated or production code on a PC', ['software-in-the-loop', 'software in the loop', 'sil', 'code', 'pc', 'compiled']], ['Processor-in-the-loop: run the code on the target processor or an equivalent, with simulated environment', ['processor-in-the-loop', 'processor in the loop', 'pil', 'target', 'processor']], ['Hardware-in-the-loop: the real ECU connected to a simulator that emulates sensors, actuators and the bus', ['hardware-in-the-loop', 'hardware in the loop', 'hil', 'real ecu', 'simulator', 'emulat']]], model: 'They are stages of testing with increasing realism. Model-in-the-loop checks the algorithm as a model in a simulation environment. Software-in-the-loop compiles the real or generated code and runs it on a PC, so I can check that the code behaves like the model. Processor-in-the-loop runs that code on the target processor or an equivalent, which exposes timing, memory and numerical differences. Hardware-in-the-loop connects the complete real ECU to a simulator that emulates sensors, actuators and bus messages, so I can test the whole system including fault cases that are dangerous to create in a real car.' },
      { q: 'What is AUTOSAR and how does ML software fit into it?', level: 'easy', points: [['A standardised software architecture for automotive ECUs, separating application from basic software', ['standard', 'architecture', 'automotive', 'application', 'basic software', 'layer', 'separat']], ['Applications are built from software components that communicate through defined interfaces', ['component', 'interface', 'runtime environment', 'rte', 'port', 'communicat']], ['The ML model is wrapped as a software component with fixed interfaces, memory and timing', ['wrap', 'component', 'model', 'interface', 'fixed', 'memory', 'timing', 'runnable']], ['Adaptive AUTOSAR suits more powerful, flexible platforms; classic suits real-time microcontrollers', ['adaptive', 'classic', 'powerful', 'microcontroller', 'platform', 'flexib', 'real-time']]], model: 'AUTOSAR is a standard software architecture for automotive ECUs. It separates application software from the basic software, such as drivers and the operating system, and the application is built from software components that talk through defined interfaces and a runtime environment. An ML function fits as one such component: the model and its inference code are wrapped, with fixed input and output interfaces, static memory and a bounded execution time that the scheduler can plan for. Classic AUTOSAR targets real-time microcontrollers, while Adaptive AUTOSAR is meant for more powerful processors where larger perception or planning models run.' },
      { q: 'What are ASIL levels, and how does machine learning complicate the safety argument?', level: 'medium', points: [['ASIL A to D classify the risk of a function, with D needing the strongest measures, from ISO 26262', ['asil', 'iso 26262', 'a to d', 'risk', 'level', 'classif', 'severity']], ['Higher levels demand more rigorous development, verification and independence', ['rigorous', 'verification', 'independen', 'process', 'measure', 'stronger', 'demand']], ['Neural networks are hard to specify and verify: no explicit requirements for each behaviour, data dependent', ['specify', 'verify', 'data', 'opaque', 'requirement', 'hard', 'explain', 'black box', 'black-box']], ['Approaches: SOTIF, safety monitors, redundancy, decomposition and thorough data and test evidence', ['sotif', 'monitor', 'redundan', 'decompos', 'evidence', 'data', 'test', 'fallback']]], model: 'ASIL, from ISO 26262, classifies how severe, how likely and how controllable a hazard is, from A for the lowest to D for the highest, and the higher the level, the more rigorous the development, verification and independence must be. Machine learning complicates this because a neural network is learned from data: I cannot write a requirement for every behaviour, review the code line by line or test every input. So the safety argument leans on other evidence: SOTIF analysis of unintended behaviour, carefully managed datasets and coverage, extensive testing, and architectural measures such as a monitor, redundancy, or ASIL decomposition with a simple safe component around the model.' },
      { q: 'What is worst-case execution time and how do you deal with it for ML inference?', level: 'medium', points: [['WCET is the longest time a piece of code could take; real-time scheduling needs it to meet deadlines', ['longest', 'worst', 'maximum', 'deadline', 'real-time', 'real time', 'schedul', 'wcet']], ['Neural network inference has a fixed amount of computation, so it is easier to bound than data-dependent code', ['fixed', 'bound', 'deterministic', 'data-dependent', 'data dependent', 'constant', 'predictable']], ['Measure on target under load, with margin; use static analysis where possible', ['measure', 'target', 'load', 'margin', 'static analysis', 'tool', 'profile']], ['Account for caches, interrupts, shared buses and accelerators; reduce model size if the budget is exceeded', ['cache', 'interrupt', 'bus', 'accelerator', 'contention', 'reduce', 'budget', 'smaller']]], model: 'The worst-case execution time is the longest an operation can take, and a real-time scheduler needs it to guarantee every deadline. A neural network is helpful here because it performs a fixed number of operations regardless of the input, with no data-dependent loops, so it can be bounded much more tightly than general code. In practice I measure many runs on the target hardware under realistic system load, add a safety margin, and use static analysis tools where available. I must remember caches, interrupts, shared buses and accelerator contention. If the bound exceeds the cycle budget, I shrink or quantise the model, or split work across cycles.' },
      { q: 'How do you version, calibrate and update ML models in a vehicle over its lifetime?', level: 'medium', points: [['Treat the model as a controlled artefact with a version, traceable to its data, training code and test results', ['version', 'artefact', 'artifact', 'traceab', 'data', 'configuration', 'release']], ['Updates over the air, signed and authenticated, with compatibility checks against the other software', ['over the air', 'ota', 'signed', 'authenticat', 'compatib', 'secure', 'update']], ['Re-validate and re-certify on each change, with regression tests on a fixed scenario set', ['validate', 'certif', 'regression', 'scenario', 'test', 'homologat', 'approval']], ['Support rollback and phased release, and keep field data processes consistent with data protection rules', ['rollback', 'phased', 'staged', 'privacy', 'data protection', 'field', 'monitor']]], model: 'A model in a car is a controlled configuration item with a version, linked to the exact data, training code and test results that produced it. Updates arrive over the air as signed and authenticated packages, and the ECU checks compatibility with the rest of the software before activating them. Every new version needs re-validation, so I keep a fixed regression set of scenarios and run it in simulation and on hardware-in-the-loop, and where regulation requires, I go through approval again. I release in phases, keep the previous version for rollback, and handle field data under data protection rules.' },
      { q: 'A neural network is part of a safety-related function and can sometimes be wrong. How do you design the system so that it is still safe?', level: 'hard', points: [['Do not rely on the network alone: add an independent simple monitor or plausibility check', ['independent', 'monitor', 'plausibility', 'check', 'simple', 'rule', 'supervis']], ['Estimate and use uncertainty or confidence, and reject inputs outside the trained domain', ['uncertain', 'confidence', 'out-of-distribution', 'out of distribution', 'domain', 'reject', 'odd']], ['Redundancy: diverse sensors or models, and a fallback to a safe state or degraded mode', ['redundan', 'diverse', 'sensor', 'fallback', 'safe state', 'degraded', 'backup']], ['Define the operating domain and test rare and edge scenarios with evidence of coverage', ['operating domain', 'odd', 'edge', 'rare', 'scenario', 'coverage', 'evidence']], ['Monitor in operation and feed incidents back into data and tests', ['operation', 'field', 'incident', 'feedback', 'monitor', 'retrain', 'data']]], model: 'I assume the network will sometimes be wrong and design the system around that. An independent, simple monitor checks the output for plausibility, for example physical limits or consistency with other sensors. I use confidence or uncertainty estimates and detect inputs outside the operating domain the model was trained for, and in those cases I do not trust it. Redundancy helps: diverse sensors or a second model, and a defined fallback or safe state when the checks fail. I define the operating domain explicitly and gather evidence by testing rare and edge scenarios with coverage metrics. After release I monitor field incidents and feed them back into the data and tests.' }
    ]
  },

  {
    id: 'cloud-deploy', title: 'Cloud deployment for ML', tracks: ['mlops', 'mle', 'genai', 'ds'],
    tasks: [
      {
        id: 'cloud-hpa', title: 'Autoscaling: how many replicas?',
        prompt: `The Kubernetes Horizontal Pod Autoscaler chooses the replica count from a metric such as CPU or requests per pod:

\`desired = ceil(current_replicas * current_metric / target_metric)\`

Write \`desired_replicas(current, metric, target, min_r, max_r)\` and clamp the result to \`[min_r, max_r]\`.`,
        starter: R`import math

def desired_replicas(current, metric, target, min_r, max_r):
    pass

print(desired_replicas(4, 90, 60, 1, 10))  # 6
`,
        solution: R`import math

def desired_replicas(current, metric, target, min_r, max_r):
    desired = math.ceil(current * metric / target)
    return max(min_r, min(max_r, desired))
`,
        tests: [
          { name: 'Scale up', code: R`assert desired_replicas(4, 90, 60, 1, 10) == 6, '4 pods at 90% with a 60% target need 6 pods'` },
          { name: 'Scale down, limited by the minimum', code: R`assert desired_replicas(4, 30, 60, 2, 10) == 2 and desired_replicas(4, 10, 60, 2, 10) == 2, 'Half the load needs 2 pods; never go below min_r'` },
          { name: 'Limited by the maximum', code: R`assert desired_replicas(10, 200, 50, 1, 20) == 20, '40 would be needed but max_r is 20'` },
          { name: 'Round up and steady state', code: R`assert desired_replicas(3, 61, 60, 1, 10) == 4 and desired_replicas(3, 60, 60, 1, 10) == 3, 'Slightly over target rounds up; exactly on target stays the same'` }
        ]
      },
      {
        id: 'cloud-bucket', title: 'Token-bucket rate limiter',
        prompt: `APIs protect themselves, and control cost, with rate limits. Write a class \`TokenBucket(rate, capacity)\`:

- The bucket starts full with \`capacity\` tokens and refills at \`rate\` tokens per second, never above \`capacity\`.
- \`allow(now)\` receives the current time in seconds (non-decreasing). Refill for the time passed since the last call, then if at least one token is available, take one and return \`True\`; otherwise return \`False\`.`,
        starter: R`class TokenBucket:
    def __init__(self, rate, capacity):
        pass

    def allow(self, now):
        pass
`,
        solution: R`class TokenBucket:
    def __init__(self, rate, capacity):
        self.rate = rate
        self.capacity = capacity
        self.tokens = float(capacity)
        self.last = None

    def allow(self, now):
        if self.last is not None:
            self.tokens = min(self.capacity, self.tokens + (now - self.last) * self.rate)
        self.last = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False
`,
        tests: [
          { name: 'Burst up to capacity', code: R`b = TokenBucket(1, 2)
assert [b.allow(0), b.allow(0), b.allow(0)] == [True, True, False], 'A full bucket of 2 allows two requests, then refuses'` },
          { name: 'Refills over time', code: R`b = TokenBucket(1, 2)
b.allow(0); b.allow(0)
assert [b.allow(1.0), b.allow(1.5), b.allow(2.0)] == [True, False, True], 'One token per second: allowed at t=1, not at t=1.5, allowed at t=2'` },
          { name: 'Never exceeds capacity', code: R`b = TokenBucket(10, 3)
b.allow(0)
assert [b.allow(100), b.allow(100), b.allow(100), b.allow(100)] == [True, True, True, False], 'After a long idle time the bucket holds only capacity tokens'` },
          { name: 'Fractional rate', code: R`b = TokenBucket(0.5, 1)
assert [b.allow(0), b.allow(1), b.allow(2)] == [True, False, True], 'At 0.5 tokens per second a new token takes 2 seconds'` }
        ]
      }
    ],
    quiz: [
      { q: 'What does a container image give you for ML deployment?', options: ['Free GPUs', 'The code, dependencies and system libraries packaged so it runs the same everywhere', 'Automatic scaling', 'A database'], answer: 1, why: 'It removes "works on my machine". Scaling comes from the orchestrator, such as Kubernetes.', level: 'easy' },
      { q: 'A model is called a few times an hour and takes 200 ms. Most cost-effective hosting?', options: ['A dedicated GPU cluster', 'Serverless or scale-to-zero, accepting an occasional cold start', 'Ten always-on replicas', 'A mainframe'], answer: 1, why: 'You pay per request. For steady high traffic, always-on instances are cheaper.', level: 'medium' },
      { q: 'What is a cold start?', options: ['A GPU overheating', 'The delay when a new instance must start and load the model before serving', 'Training from scratch', 'A failed deployment'], answer: 1, why: 'Large models make it worse. Mitigate with a minimum number of warm instances or smaller images.', level: 'easy' },
      { q: 'Readiness probe versus liveness probe in Kubernetes?', options: ['They are identical', 'Readiness: can this pod receive traffic yet? Liveness: is it stuck and in need of a restart?', 'Liveness checks the GPU', 'Readiness restarts the pod'], answer: 1, why: 'A model server should report ready only after the model is loaded.', level: 'medium' },
      { q: 'What is a Dockerfile?', options: ['A log of container errors', 'A running container', 'A text recipe describing how to build an image', 'A Kubernetes cluster'], answer: 2, why: 'Each instruction becomes a layer of the image.', level: 'easy' },
      { q: 'Horizontal scaling means…', options: ['Adding more replicas of the service', 'Giving one machine more CPU and RAM', 'Moving the service to a new region', 'Compressing the model'], answer: 0, why: 'Giving one machine more resources is vertical scaling.', level: 'easy' },
      { q: 'A pod restarts repeatedly and its status shows OOMKilled. What happened?', options: ['The GPU overheated', 'The image was too old', 'The container exceeded its memory limit and was killed', 'The health endpoint returned 200'], answer: 2, why: 'Raise the limit, reduce memory use, or run fewer workers per pod.', level: 'medium' },
      { q: 'Traffic jumps every weekday at 09:00. What helps most?', options: ['Scale to zero overnight and nothing else', 'Raise the minimum replicas, or scale on a schedule, shortly before 09:00, in addition to autoscaling', 'Increase the log level', 'Use a larger Docker image'], answer: 1, why: 'Reactive autoscaling lags a sudden spike, so prepare capacity in advance.', level: 'medium' },
      { q: 'Out of 1,000 requests, 20 take 3 s and 980 take 50 ms. Which statement is right?', options: ['The mean and p99 are both about 50 ms', 'The mean is 3 s', 'The p99 is 50 ms because most requests are fast', 'The mean is about 109 ms but p99 is about 3 s, so the mean hides the tail'], answer: 3, why: 'The slowest 2% exceed the top 1%, so p99 lands among the slow requests.', level: 'hard' },
      { q: 'A dependency becomes slow and every client retries immediately, three times per failure. What is the likely effect and the fix?', options: ['Load multiplies and the outage worsens: use capped exponential back-off with jitter', 'Load drops, because retries are cheap', 'Nothing changes', 'Latency falls because retries are parallel'], answer: 0, why: 'Unlimited immediate retries turn a slowdown into an outage.', level: 'hard' },
      { q: 'A canary gets 5% of traffic. The overall error rate rises from 0.1% to 0.5%. Assuming the other 95% still has 0.1% errors, roughly what is the canary’s error rate?', options: ['About 0.5%', 'About 8%', 'About 4%', 'About 0.1%'], answer: 1, why: '0.95 × 0.1% + 0.05 × x = 0.5% gives x of about 8%.', level: 'hard' },
      { q: 'How can spot or preemptible instances still serve part of a production inference API?', options: ['They never can', 'They have no memory limit', 'They are never interrupted', 'With several replicas, graceful draining on the interruption notice, and on-demand capacity as a fallback'], answer: 3, why: 'Interruption is expected, so the design must tolerate it.', level: 'hard' }
    ],
    interview: [
      { q: 'How would you deploy an ML model as an API in the cloud?', level: 'medium', points: [['Wrap the model in an API service', ['api', 'fastapi', 'rest', 'grpc', 'endpoint']], ['Package in a container', ['container', 'docker', 'image']], ['Run on a managed service or Kubernetes with autoscaling', ['kubernetes', 'managed', 'autoscal', 'sagemaker', 'vertex', 'azure', 'serverless']], ['CI/CD and infrastructure as code', ['ci', 'pipeline', 'terraform', 'infrastructure as code', 'deploy']], ['Observability, security and cost', ['monitor', 'log', 'secur', 'cost', 'auth']]], model: 'I wrap the model in a small service with a health endpoint and a prediction endpoint, validate inputs, and load the model once at start-up. I package it in a container image with pinned dependencies and store it in a registry. For hosting I choose by traffic: a managed endpoint or serverless container for simple or bursty workloads, Kubernetes when I need control, GPUs or many services. I add autoscaling, readiness checks, and a load balancer with authentication and rate limiting. A CI/CD pipeline tests, builds and rolls out the image gradually, and the infrastructure is defined as code. I monitor latency percentiles, errors, cost and model quality, and keep rollback simple.' },
      { q: 'How do you control the cost of ML workloads in the cloud?', level: 'medium', points: [['Right-size and autoscale, scale to zero when idle', ['right-siz', 'autoscal', 'scale to zero', 'idle']], ['Cheaper capacity: spot or reserved instances', ['spot', 'reserved', 'preemptible', 'commit']], ['Make the model cheaper: quantise, distil, batch, cache', ['quanti', 'distil', 'batch', 'cache']], ['Measure cost per request and set budgets and alerts', ['cost per', 'budget', 'alert', 'tag', 'measure']]], model: 'I first make cost visible: tag resources, track cost per request or per training run, and set budgets with alerts. For serving, I right-size instances, autoscale on a meaningful metric and scale to zero where latency allows. I use reserved capacity for steady load and spot instances for fault-tolerant work such as training and batch inference. Then I reduce the work itself: quantise or distil the model, batch requests on GPUs, cache repeated results, and for LLM applications trim prompts, cache prefixes and route easy requests to a smaller model. I also clean up idle endpoints, old snapshots and oversized storage.' },
      { q: 'When would you choose serverless, containers on Kubernetes, or a managed ML endpoint?', level: 'hard', points: [['Serverless: bursty or low traffic, minimal operations, cold starts and limits', ['serverless', 'burst', 'cold start', 'low traffic']], ['Managed endpoint: quick, built-in scaling and monitoring, less control', ['managed', 'sagemaker', 'vertex', 'azure ml', 'built-in']], ['Kubernetes: full control, GPUs, many services, needs a platform team', ['kubernetes', 'control', 'gpu', 'team']], ['Decide by traffic pattern, latency, team skills and cost', ['traffic', 'latency', 'team', 'cost', 'depends']]], model: 'Serverless fits spiky or low traffic and small models: there is nothing to operate and you pay per request, but cold starts, time limits and limited GPU support restrict it. A managed ML endpoint gets a model online quickly with autoscaling, versioning and monitoring built in, at a higher unit price and with less flexibility. Kubernetes gives full control over hardware, networking and rollout strategies and is efficient at scale, but it needs people who can run it. I decide from the traffic pattern, latency target, whether GPUs are needed, the team’s operating skills and total cost, and I avoid adopting Kubernetes for a single small service.' },
      { q: 'What is a container, and why are containers used for ML services?', level: 'easy', points: [['A container packages code, libraries and dependencies into a portable image that runs the same everywhere', ['package', 'portable', 'image', 'dependenc', 'same', 'everywhere', 'docker']], ['It solves works-on-my-machine problems and pins versions for reproducibility', ['reproduc', 'version', 'pin', 'machine', 'consistent', 'environment']], ['Lightweight compared with virtual machines: shares the host kernel and starts quickly', ['lightweight', 'virtual machine', 'kernel', 'fast', 'start', 'share', 'vm']], ['ML specifics: large images, GPU drivers and model weights, kept outside the image or in layers', ['gpu', 'driver', 'weights', 'large', 'image size', 'layer', 'cuda']]], model: 'A container bundles my application, its libraries and the runtime into an image that runs the same on a laptop, a test server and in the cloud. For ML that matters a lot, because versions of Python packages, CUDA and drivers must match, and a container pins them for reproducibility and removes the works-on-my-machine problem. Containers share the host kernel, so they are much lighter and faster to start than virtual machines, which helps autoscaling. For ML I keep images lean, use a GPU-ready base image, and load the large model weights from storage at start-up or mount them, instead of baking everything into one huge image.' },
      { q: 'What is autoscaling and which signals would you use to trigger it?', level: 'easy', points: [['Automatically adding or removing instances according to load', ['add', 'remove', 'instance', 'replica', 'automatic', 'load', 'scale out', 'scale in']], ['Signals: CPU or GPU utilisation, requests per second, concurrency and queue length', ['cpu', 'gpu', 'utilis', 'utiliz', 'request', 'concurren', 'queue', 'rps']], ['Latency targets are good user-facing signals; cold start and warm-up time limit how fast it can react', ['latency', 'cold start', 'warm-up', 'warm up', 'react', 'slow', 'lag']], ['Set minimum and maximum limits and cool-down to avoid flapping and cost surprises', ['minimum', 'maximum', 'limit', 'cool-down', 'cooldown', 'flapping', 'budget', 'cost']]], model: 'Autoscaling adds or removes copies of a service automatically as load changes, so I do not pay for idle capacity or fall over at peak. I choose the trigger by what actually limits the service: CPU or GPU utilisation, requests per second, concurrent requests, or queue length for asynchronous work. A latency target is a good signal because it is what users feel. For ML there is a catch: loading a model takes time, so new instances may need a minute or more before they are useful. I set minimum and maximum replicas and a cool-down to avoid flapping, and keep headroom for sudden spikes.' },
      { q: 'What is infrastructure as code and why use it?', level: 'easy', points: [['Describing cloud resources in versioned configuration files instead of clicking in a console', ['configuration', 'file', 'code', 'version', 'declare', 'console', 'describe']], ['Tools such as Terraform or similar create and update the resources from those files', ['terraform', 'tool', 'create', 'update', 'apply', 'cloudformation', 'pulumi']], ['Benefits: reproducible environments, review through pull requests, and easy recreation', ['reproduc', 'review', 'pull request', 'recreate', 'consisten', 'audit', 'repeat']], ['Helps avoid configuration drift and speeds up disaster recovery', ['drift', 'disaster', 'recovery', 'rebuild', 'manual', 'same']]], model: 'Infrastructure as code means I define networks, clusters, storage and permissions in versioned files, and a tool such as Terraform creates and updates them to match. Because it is just code, I get the usual benefits: changes are reviewed in pull requests, the history is auditable, and I can stand up an identical staging or production environment on demand. It avoids configuration drift, where hand-made changes make environments subtly different, and it makes disaster recovery much faster since I can rebuild everything from the repository. For ML I describe the GPU node pools, endpoints and storage the same way.' },
      { q: 'Explain blue-green and canary deployments for a model API, and how rollback works.', level: 'medium', points: [['Blue-green: run the new version beside the old, then switch all traffic at once', ['blue-green', 'blue green', 'beside', 'switch', 'all traffic', 'two environment', 'parallel']], ['Canary: route a small share of traffic to the new version and grow it while monitoring', ['canary', 'small', 'share', 'percent', 'grow', 'gradual', 'monitor']], ['Health and quality checks decide whether to proceed: errors, latency and model metrics', ['health', 'error', 'latency', 'metric', 'quality', 'check', 'decide']], ['Rollback means routing traffic back to the old version, which is why it stays running until the new one is proven', ['rollback', 'roll back', 'route back', 'old version', 'stay', 'previous', 'revert']]], model: 'In a blue-green deployment I run the new version, green, next to the current one, blue, test it, and then switch all traffic over, which makes rollback instant: I switch back. A canary release is more gradual: I send a small percentage of real traffic to the new version, watch error rate, latency and model quality metrics, and increase the share only while everything is healthy. For a model API I also compare prediction distributions between versions. In both cases the old version keeps running until the new one has been proven, and an automatic check can route traffic back if a threshold is breached.' },
      { q: 'How do you serve GPU-based models efficiently, including large language models?', level: 'medium', points: [['Batch requests, with dynamic or continuous batching, to keep the GPU busy', ['batch', 'dynamic', 'continuous', 'busy', 'utilis', 'utiliz', 'throughput']], ['Use an optimised inference server and engine, with quantisation or lower precision', ['inference server', 'engine', 'tensorrt', 'triton', 'vllm', 'quantis', 'quantiz', 'precision', 'optimis']], ['Share GPUs between models or slice them to avoid waste, and size instances to memory needs', ['share', 'slice', 'mig', 'multi-model', 'multi model', 'memory', 'size', 'waste']], ['Balance latency and throughput, and use caching such as a key-value cache for LLMs', ['latency', 'throughput', 'cache', 'kv', 'key-value', 'key value', 'trade']]], model: 'A GPU is expensive, so the aim is to keep it busy without breaking the latency target. I batch requests dynamically, which means waiting a few milliseconds to group them, and for language models I use continuous batching so new requests join in-flight batches. I use an optimised inference server and engine, with lower precision or quantisation to cut memory and increase speed, and a key-value cache for LLM decoding. Smaller models can share one GPU, or I partition a GPU so each gets a slice, and I size instances to the memory the model needs. The core trade-off is larger batches for throughput versus higher latency.' },
      { q: 'Traffic to your GPU-backed model endpoint is spiky and cold starts are slow. How do you design for that?', level: 'hard', points: [['Cold start comes from provisioning a GPU node, pulling a large image and loading weights', ['provision', 'image', 'pull', 'load', 'weights', 'node', 'cold start']], ['Keep a minimum number of warm instances, or scale on predicted load', ['warm', 'minimum', 'pre-warm', 'prewarm', 'schedule', 'predict', 'headroom']], ['Speed up start-up: smaller images, cached images and weights on local disk, lazy loading', ['smaller', 'cache', 'local', 'faster', 'lazy', 'optimis', 'start-up', 'startup']], ['Absorb spikes with a queue, rate limiting or graceful degradation to a smaller model', ['queue', 'rate limit', 'degrad', 'smaller model', 'fallback', 'backpressure', 'shed']], ['Weigh the cost of warm capacity against latency requirements', ['cost', 'trade', 'latency', 'requirement', 'budget', 'balance']]], model: 'Cold start has three parts: getting a GPU node, pulling a big container image and loading the model weights. To handle spikes, I keep a minimum number of warm replicas and add headroom, or pre-scale on a schedule or a forecast when traffic is predictable. I shorten start-up by using smaller images, caching images and weights on local disks, and loading weights efficiently. For the burst itself, I put a queue or rate limiter in front for asynchronous work, apply backpressure, or degrade gracefully to a smaller, faster model. The final decision balances the cost of idle warm GPUs against the latency the product needs.' },
      { q: 'How would you secure a multi-tenant ML inference API in the cloud?', level: 'hard', points: [['Authenticate and authorise every request with scoped credentials, and isolate tenants logically in data and quotas', ['authenticat', 'authoris', 'authoriz', 'credential', 'token', 'tenant', 'isolat', 'quota']], ['Encrypt in transit and at rest, manage secrets in a vault, never in images or code', ['encrypt', 'tls', 'secret', 'vault', 'key', 'rest', 'transit']], ['Network controls: private networking, least-privilege roles, rate limiting and a gateway', ['network', 'private', 'least privilege', 'role', 'rate limit', 'gateway', 'firewall']], ['Protect data: avoid logging sensitive inputs, retention limits, no cross-tenant leakage via caches or training', ['logging', 'sensitive', 'retention', 'leak', 'cache', 'privacy', 'personal', 'training']], ['Audit logs, monitoring for abuse and model-specific threats such as extraction', ['audit', 'monitor', 'abuse', 'extraction', 'anomal', 'log', 'alert']]], model: 'Every request is authenticated and authorised with scoped tokens, and each tenant has its own quotas, rate limits and logically separated data so one tenant can never see or slow down another. Traffic is encrypted in transit and data at rest, secrets live in a vault and are injected at run time, never baked into images. The service runs in a private network behind a gateway with least-privilege roles. I avoid logging sensitive inputs, set retention limits, and make sure caches and any fine-tuning or feedback data are partitioned per tenant. Finally, audit logs and monitoring detect abuse, including attempts to extract the model through massive querying.' }
    ]
  }
];
